            ),
            ("b", "[dependencies]\na = { path = \"../a\" }\n"),
            ("c", "[dev-dependencies]\na = { path = \"../a\" }\n"),
        ]));
        let error = derive(&dir, &cargo_release(&["a", "b", "c"])).unwrap_err();
        assert!(matches!(error, GraphError::Cycle { .. }), "{error:?}");
    }

